def test_register_offsets(regs):
    assert regs.DW_CAPTURE_REG.address == 0x0
    assert regs.DR_START_REG.address == 0x4
    assert regs.STATUS_REG.address == 0x8
    assert regs.DEBUG_REG.address == 0x3c


def test_field_roundtrip(regs):
    regs.DW_CAPTURE_REG.DW_CAPTURE.write(0x1)
    assert regs.DW_CAPTURE_REG.DW_CAPTURE.read() == 0x1
    regs.DW_CAPTURE_REG.DW_CAPTURE.write(0)
    regs.DR_START_REG.DR_START.write(0x1)
    assert regs.DR_START_REG.DR_START.read() == 0x1
    regs.DR_START_REG.DR_START.write(0)
    regs.DEBUG_REG.FORCE_TRIGGER.write(0x1)
    assert regs.DEBUG_REG.FORCE_TRIGGER.read() == 0x1
    regs.DEBUG_REG.FORCE_TRIGGER.write(0)
    regs.DEBUG_REG.FORCE_TREADY.write(0x1)
    assert regs.DEBUG_REG.FORCE_TREADY.read() == 0x1
    regs.DEBUG_REG.FORCE_TREADY.write(0)


def test_register_independence(regs):
    regs.DW_CAPTURE_REG.DW_CAPTURE.write(0x1)
    regs.DR_START_REG.DR_START.write(0x1)
    regs.DEBUG_REG.FORCE_TRIGGER.write(0x1)
    regs.DEBUG_REG.FORCE_TREADY.write(0x1)
    assert regs.DW_CAPTURE_REG.DW_CAPTURE.read() == 0x1
    assert regs.DR_START_REG.DR_START.read() == 0x1
    assert regs.DEBUG_REG.FORCE_TRIGGER.read() == 0x1
    assert regs.DEBUG_REG.FORCE_TREADY.read() == 0x1
